<?php require __DIR__.'/../inc/bootstrap.php'; require_admin(); $posts=load_json('posts.json',array()); if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['delete'])){ verify_csrf(); $id=(string)$_POST['delete']; $filtered=array(); foreach($posts as $p){if((string)$p['id']!==$id)$filtered[]=$p;} $posts=$filtered; save_json('posts.json',$posts); header('Location: posts.php');exit;} ?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>POSTS</title><link rel="stylesheet" href="../assets/style.css"></head><body><main class="container"><div class="card"><h1>[ LOG MANAGEMENT ]</h1><p><a href="post_edit.php">+ NEW LOG</a> | <a href="index.php">BACK</a></p><?php foreach(array_reverse($posts) as $p): ?><article class="card"><div class="post-title"><?=e($p['title'])?></div><div class="post-meta"><?=e(isset($p['date'])?$p['date']:'')?></div><a href="post_edit.php?id=<?=urlencode($p['id'])?>">EDIT</a> | <form method="post" style="display:inline" onsubmit="return confirm('Delete this log?')"><?=csrf_field()?><input type="hidden" name="delete" value="<?=e($p['id'])?>"><button type="submit">DELETE</button></form></article><?php endforeach; ?></div></main></body></html>
